import re, glob, os
sys_pat = re.compile(r'py_extract\(([^()]*?(?:\([^()]*\)[^()]*?)*)\)')
# resolve constants
consts = {}
for f in ['UtilityScripts/BankRegexConstants.py','UtilityScripts/RegexConstants.py']:
    for line in open(f):
        m = re.match(r'^([A-Z0-9_]+)\s*=\s*(.+)$', line.strip())
        if m:
            try: consts[m.group(1)] = eval(m.group(2), {}, {})
            except Exception: pass
for f in sorted(glob.glob('BankScripts/*.py'))+sorted(glob.glob('UtilityScripts/*.py')):
    for i, line in enumerate(open(f), 1):
        for m in re.finditer(r'py_extract\((.*?), index=(\d+)\)', line):
            args, idx = m.group(1), int(m.group(2))
            pm = re.search(r'pat=(.*)$', args)
            if not pm: 
                print("??", f, i, args); continue
            p = pm.group(1).strip()
            pat = None
            if p in consts: pat = consts[p]
            else:
                try: pat = eval(p, {}, {})
                except Exception: pass
            if pat is None:
                print("unresolved", f, i, p); continue
            try: ng = re.compile(pat).groups
            except Exception as e: print("bad", f,i,e); continue
            flag = "  <-- MISMATCH" if ng != idx+1 else ""
            if flag: print(f"{f}:{i} groups={ng} index={idx} pat={pat!r}{flag}")
